CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied TEXT NOT NULL);
CREATE TABLE workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,path TEXT NOT NULL UNIQUE,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)));
CREATE TABLE goals(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,criteria TEXT NOT NULL,constraints_json TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','active','paused','blocked','completed','archived')),priority INTEGER CHECK(priority BETWEEN 1 AND 5),workspace_id TEXT NOT NULL REFERENCES workspaces,provider TEXT NOT NULL REFERENCES agent_connections,created TEXT NOT NULL,updated TEXT NOT NULL);
CREATE TABLE agent_connections(id TEXT PRIMARY KEY,state TEXT NOT NULL,detail TEXT NOT NULL);
INSERT INTO agent_connections VALUES ('demo','ready','离线演示'),('codex','unchecked','尚未检查');
CREATE TABLE agent_runs(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals,provider TEXT NOT NULL REFERENCES agent_connections,thread_id TEXT,turn_id TEXT,status TEXT NOT NULL CHECK(status IN('queued','starting','running','waiting_approval','succeeded','failed','interrupted','unknown')),instruction TEXT NOT NULL,key TEXT NOT NULL,created TEXT NOT NULL,finished TEXT,heartbeat TEXT NOT NULL,UNIQUE(goal_id,key));
CREATE UNIQUE INDEX one_live_run ON agent_runs(goal_id) WHERE status IN('queued','starting','running','waiting_approval','unknown');
CREATE INDEX run_health ON agent_runs(status,heartbeat);
CREATE TABLE raw_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,run_id TEXT NOT NULL REFERENCES agent_runs,goal_id TEXT NOT NULL REFERENCES goals,fingerprint TEXT NOT NULL,type TEXT NOT NULL,occurred TEXT NOT NULL,received TEXT NOT NULL,severity TEXT NOT NULL,method TEXT NOT NULL,payload TEXT NOT NULL,title TEXT NOT NULL,UNIQUE(run_id,fingerprint));
CREATE INDEX event_goal ON raw_events(goal_id,received);
CREATE INDEX event_run ON raw_events(run_id,seq);
CREATE TRIGGER immutable_event BEFORE UPDATE ON raw_events BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TABLE stories(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals,unit TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,category TEXT NOT NULL,verification TEXT NOT NULL CHECK(verification IN('reported','verified','disputed','unverified')),materiality REAL NOT NULL CHECK(materiality BETWEEN 0 AND 1),version INTEGER NOT NULL,last_seq INTEGER NOT NULL REFERENCES raw_events(seq),updated TEXT NOT NULL,UNIQUE(goal_id,unit));
CREATE INDEX story_goal ON stories(goal_id,updated);
CREATE TABLE story_events(story_id TEXT REFERENCES stories,event_id TEXT REFERENCES raw_events(id),PRIMARY KEY(story_id,event_id));
CREATE TABLE story_versions(story_id TEXT REFERENCES stories,version INTEGER,summary TEXT NOT NULL,verification TEXT NOT NULL,evidence_id TEXT REFERENCES raw_events(id),PRIMARY KEY(story_id,version));
CREATE TABLE artifacts(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES agent_runs,goal_id TEXT NOT NULL REFERENCES goals,story_id TEXT REFERENCES stories,path TEXT NOT NULL,verified TEXT,kind TEXT NOT NULL,UNIQUE(run_id,path));
CREATE TABLE briefings(id TEXT PRIMARY KEY,revision TEXT NOT NULL UNIQUE,source_cursor INTEGER NOT NULL,end_seq INTEGER NOT NULL,window_start TEXT,window_end TEXT NOT NULL,generated TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TRIGGER immutable_briefing BEFORE UPDATE ON briefings BEGIN SELECT RAISE(ABORT,'immutable snapshot'); END;
CREATE TABLE briefing_stories(briefing_id TEXT REFERENCES briefings,story_id TEXT REFERENCES stories,version INTEGER NOT NULL,section TEXT NOT NULL,rank INTEGER NOT NULL,summary TEXT NOT NULL,PRIMARY KEY(briefing_id,story_id));
CREATE TABLE attention_cursors(id INTEGER PRIMARY KEY CHECK(id=1),seq INTEGER NOT NULL,briefing_id TEXT REFERENCES briefings,reviewed TEXT);
INSERT INTO attention_cursors VALUES(1,0,NULL,NULL);
CREATE TABLE inbox_items(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals,run_id TEXT NOT NULL REFERENCES agent_runs,request_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','deferred','approved','denied','expired','cancelled','resolved')),title TEXT NOT NULL,action TEXT NOT NULL,reason TEXT NOT NULL,scope TEXT NOT NULL,risk TEXT NOT NULL,created TEXT NOT NULL,expires TEXT,version INTEGER NOT NULL DEFAULT 1,UNIQUE(run_id,request_id));
CREATE INDEX inbox_queue ON inbox_items(status,created);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,key TEXT,detail TEXT NOT NULL,created TEXT NOT NULL,UNIQUE(target,key));
CREATE TABLE schedule_jobs(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals,kind TEXT NOT NULL CHECK(kind IN('one_off','interval')),instruction TEXT NOT NULL,minutes INTEGER NOT NULL,next_at TEXT NOT NULL,state TEXT NOT NULL,lease TEXT,lease_until TEXT,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,last_run TEXT);
CREATE INDEX due_jobs ON schedule_jobs(state,next_at);
CREATE TABLE user_messages(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals,scope TEXT NOT NULL,ref TEXT NOT NULL,content TEXT NOT NULL,created TEXT NOT NULL,status TEXT NOT NULL,run_id TEXT REFERENCES agent_runs);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),config TEXT NOT NULL);
INSERT INTO settings VALUES(1,'{"dailyTime":"09:00","lastDaily":"","budget":4,"cooldown":10,"maxMinutes":30}');

